    ranad:(f,t,v,out)=>{const [k]=near(PITCH.ranad,f);return ranadKey(+k.slice(1),t,v,out)},
    thum:(k,t,v,out)=>{k=Math.round(k);while(k<0)k+=7;while(k>21)k-=7;const e=RK[k];return e?play(e[0],t,(v==null?1:v)*1.1,.5,0,out,1400):false},
    khlui:(f,t,dur,v,out)=>pitched('khlui',f,t,v,dur||.6,out),
    sor:(f,t,dur,v,out)=>pitched('sor',f,t,v,dur||.5,out),
    thon:(k,t,v,out)=>play(THON[Math.max(0,Math.min(3,k|0))],t,v,1,0,out),
    /* กลองหลวงแม่สอด (อัดจริง 3 ครั้ง ตัดเสียงคนออกด้วยการเก็บเฉพาะเสียงตีและเสียงก้องของกลอง) k 0–2 */
    klong:(k,t,v,out)=>play(['kl_1','kl_2','kl_3'][Math.max(0,Math.min(2,k|0))],t,v,1,0,out),
    /* ฉาบและฆ้องของวงกลองหลวงแม่สอด สกัดจากคลิปซ้อมจริง: ฉาบ = สเปกตรัมเฉลี่ยจากการตีฉาบ 118 ครั้งที่ไม่ทับกลอง (เสียงคนเฉลี่ยหายไป) · ฆ้อง = ความถี่/ความดัง/การลดเสียงของ 12 โหมดที่วัดจากการตีฆ้อง 72 ครั้ง */
